# ------------------------------------------------------------ full-hand CFR strategy
# Learned offline by self-play (tools/cfr_full.py). Key: seat, street, strength group,
# pot class at street start, abstract actions this street, ":" legal abstract actions.
CFR_STREET = {"preflop": 0, "flop": 1, "turn": 2, "river": 3}
CFR_POT_CUTS = (4, 8, 16, 32, 64, 128, 256)
CFR_PREFIX = {}
for _k, _v in CFR_TABLE.items():
    _pre = _k.split(":")[0]
    _o = CFR_PREFIX.get(_pre)
    if _o is None or _v[-1] > CFR_TABLE[_o][-1]:
        CFR_PREFIX[_pre] = _k


def cfr_hs(pair, board, n):
    known = set(pair) | set(board)
    rest = [c for c in range(52) if c not in known]
    need = 5 - len(board)
    tot = 0.0
    sample = random.sample
    for _ in range(n):
        s = sample(rest, 2 + need)
        full = board + s[2:] if need else board
        a = ev(pair + full)
        b = ev(s[:2] + full)
        tot += 1.0 if a > b else (0.5 if a == b else 0.0)
    return tot / n


def cfr_group_of(x, cuts):
    for i, c in enumerate(cuts):
        if x <= c:
            return i
    return len(cuts)


def cfr_strength(hole, board, n):
    if not board:
        return PREFLOP[canon3(hole)][0] if len(hole) == 3 else 0.5
    if len(hole) == 3:
        a, b, c = hole
        return max(cfr_hs([a, b], board, n), cfr_hs([a, c], board, n), cfr_hs([b, c], board, n))
    return cfr_hs(hole, board, n)


def cfr_labels(contrib_p, contrib_o, my_bet, opp_bet, raises, last_raise):
    to_call = opp_bet - my_bet
    max_to = min(my_bet + 200 - contrib_p, opp_bet + 200 - contrib_o)
    labs = ["f", "c"] if to_call > 0 else ["k"]
    if raises < 4 and max_to > opp_bet:
        pot_after = contrib_p + contrib_o + to_call
        min_to = min(opp_bet + max(last_raise, 2), max_to)
        seen = set()
        for frac, lab in ((0.5, "h"), (1.0, "p")):
            to = max(min_to, opp_bet + int(round(frac * pot_after)))
            if to >= 0.85 * max_to or to in seen:
                continue
            seen.add(to)
            labs.append(lab)
        labs.append("a")
    return "".join(labs)


# ---------------------------------------------------------- opponent model

class OppModel:
    def __init__(self):
        self.actions = 8.0
        self.raises = 2.0
        self.faced = 8.0      # times opp faced our bet/raise
        self.folds = 3.0      # times opp folded to it
        self.faced_rr = 6.0   # times opp faced our raise after they had bet/raised on that street
        self.folds_rr = 1.2   # times they folded to it
        self.faced_post = 10.0  # times opp faced our postflop bet/raise
        self.raised_post = 1.5  # times they raised it
        self.big_bets_shown = 6.0
        self.bluffs_shown = 1.5
        self.hands = 0
        # (street, size bucket or 3 for a re-raise) -> [sum of shown strength, count]
        self.bet_obs = {}
        # same key -> list of the shown strengths (latest 60)
        self.bet_list = {}

    @property
    def raise_rate(self):
        return self.raises / self.actions

    @property
    def fold_rate(self):
        return self.folds / self.faced

    @property
    def fold_rr_rate(self):
        return self.folds_rr / self.faced_rr

    @property
    def raise_post_rate(self):
        return self.raised_post / self.faced_post

    def rr_scale(self):
        """Raises over our bets are read as strong; less so against opponents who raise our bets often."""
        r = max(0.03, self.raise_post_rate)
        return min(1.3, max(0.35, (P["rr_base"] / r) ** P["rr_pow"]))

    @property
    def bluff_rate(self):
        return self.bluffs_shown / self.big_bets_shown

    def learn_bets(self, hist, msg):
        opp = [CARD_INDEX[c] for c in msg["opp_hole_cards"]]
        board = [CARD_INDEX[c] for c in msg["board"]]
        n_board = {"flop": 3, "turn": 4, "river": 5}
        raised = {}
        for i, st, actor, act, amt, size in replay(hist):
            if act != "raise":
                continue
            prior = raised.get(st, 0)
            raised[st] = prior + 1
            if actor != "opp" or st not in n_board or len(board) < n_board[st]:
                continue
            b = 3 if prior >= 1 else size_bucket(size)
            stg = made_strength(opp, board[:n_board[st]])
            o = self.bet_obs.setdefault((st, b), [0.0, 0])
            o[0] += stg
            o[1] += 1
            lst = self.bet_list.setdefault((st, b), [])
            lst.append(stg)
            del lst[:-60]

    def update(self, msg):
        self.hands += 1
        hist = msg.get("history") or []
        last_me_raise = False
        last_me_rr = False
        opp_raised_on = set()
        for h in hist:
            actor = h.get("actor")
            act = h.get("action")
            st = h.get("street")
            if actor == "opp":
                self.actions += 1
                if act == "raise":
                    self.raises += 1
                    opp_raised_on.add(st)
                if last_me_raise:
                    self.faced += 1
                    if act == "fold":
                        self.folds += 1
                    if st != "preflop":
                        self.faced_post += 1
                        if act == "raise":
                            self.raised_post += 1
                if last_me_rr:
                    self.faced_rr += 1
                    if act == "fold":
                        self.folds_rr += 1
                last_me_raise = False
                last_me_rr = False
            else:
                last_me_raise = act == "raise"
                last_me_rr = act == "raise" and st in opp_raised_on
        if msg.get("result") == "showdown" and msg.get("opp_hole_cards"):
            try:
                self.learn_bets(hist, msg)
            except Exception:
                pass
            opp_late_raise = any(h.get("actor") == "opp" and h.get("action") == "raise"
                                 and h.get("street") in ("turn", "river") for h in hist)
            if opp_late_raise:
                try:
                    opp = [CARD_INDEX[c] for c in msg["opp_hole_cards"]]
                    board = [CARD_INDEX[c] for c in msg["board"]]
                    if len(board) == 5:
                        self.big_bets_shown += 1
                        if made_strength(opp, board) <= 0.30:
                            self.bluffs_shown += 1
                except Exception:
                    pass


# ------------------------------------------------------------------- bot

class Bot:
    def __init__(self):
        self.total_hands = 400
        self.time_bank_ms = 60000
        self.hand_id = 0
        self.hole = []
        self.opp_discard = None
        self.flop = []
        self.opp = OppModel()
        self.pf_cache = {}
        self.seat = None

    # ---- time
    def budget(self, req, mult=1.0):
        left = req.get("time_left_ms", self.time_bank_ms)
        hands_left = max(1, self.total_hands - self.hand_id + 1)
        # Target about 35% of the bank over the match (~6 budget units per hand:
        # ~4 actions plus a discard worth 2.5). Never more than the fair share of what is left.
        fixed = self.time_bank_ms * 0.55 / (max(1, self.total_hands) * 6.0)
        ms = min(fixed, left * 0.55 / (hands_left * 6.0))
        if left < 0.15 * self.time_bank_ms or left < 4000:
            ms = min(ms, 1.0)
        ms = max(0.5, min(150.0, ms * mult))
        return ms / 1000.0

    # ---- messages
    def on_message(self, msg):
        t = msg.get("type")
        if t == "init":
            self.total_hands = int(msg.get("total_hands", 400))
            self.time_bank_ms = int(msg.get("time_bank_ms", 60000))
        elif t == "new_hand":
            self.hand_id = int(msg.get("hand_id", self.hand_id + 1))
            self.hole = [CARD_INDEX[c] for c in msg.get("hole_cards", [])]
            self.seat = msg.get("seat")
            self.opp_discard = None
            self.flop = []
        elif t == "discard_result":
            hc = msg.get("hole_cards")
            if hc:
                self.hole = [CARD_INDEX[c] for c in hc]
            od = msg.get("opp_discard")
            self.opp_discard = CARD_INDEX.get(od) if od else None
        elif t == "hand_result":
            self.opp.update(msg)
        return None

    # ---- opponent range weighting
    def pressure(self, req):
        """How strongly the opponent's actions this hand narrow their range.

        Older actions use fixed weights. The opponent's latest bet or raise on the current
        street is read through what this opponent has shown down after bets of that size.
        """
        street = req.get("street")
        hist = req.get("history") or []
        p_disc = 0.0
        p_full = 0.0
        raised_on = {}
        cur_bet = None  # (bucket, default pressure) of opp's latest raise this street
        f = (0.25 / max(0.05, self.opp.raise_rate)) ** 0.7
        f = min(1.6, max(0.35, f))
        honest = (0.25 / max(0.05, self.opp.bluff_rate)) ** 0.5
        f *= min(1.6, max(0.7, honest))
        for i, st, actor, act, amt, size in replay(hist):
            if act == "raise":
                earlier = raised_on.get(st, 0) + (1 if st == "preflop" else 0)
                raised_on[st] = raised_on.get(st, 0) + 1
                if actor != "opp":
                    continue
                cur = st == street
                rr = earlier >= (2 if st == "preflop" else 1)
                if cur and st != "preflop":
                    if cur_bet is not None:  # an earlier opp raise this street: fixed weight
                        p_full += cur_bet[1]
                    dflt = P["reraise_p"] * self.opp.rr_scale() if rr else (0.8 + 0.35 * min(2.0, size or 0.0)) * f
                    cur_bet = (3 if rr else size_bucket(size or 0.0), dflt)
                elif rr:
                    p_full += P["reraise_p"] if cur else 0.6
                else:
                    p_disc += 0.8 if cur else 0.45
            elif act == "call" and actor == "opp":
                if raised_on.get(st, 0) >= 1 and st != "preflop":
                    p_full += P["callraise_p"] if st == street else P["callraise_p"] * 0.7
                else:
                    p_disc += 0.15
        if street == "preflop":
            to_call = req.get("to_call", 0)
            pot = req.get("pot", 0)
            if to_call > 0 and pot - to_call > 0:
                p_disc += 0.35 * min(2.0, to_call / float(pot - to_call))
        total = p_disc * f + p_full
        if cur_bet is not None:
            b, dflt = cur_bet
            m0 = strength_of_pressure(dflt)
            o = self.opp.bet_obs.get((street, b))
            k = P["learn_k"]
            if o:
                m = (o[0] + m0 * k) / (o[1] + k)
                pm = pressure_of_strength(m)
                if b == 3:  # showdowns after raises over our bets skip the bluffs we folded to
                    pm *= self.opp.rr_scale()
                total += pm
            else:
                total += dflt
        return min(5.0, total)

    def street_raises(self, req):
        street = req.get("street")
        return sum(1 for h in req.get("history") or [] if h.get("street") == street and h.get("action") == "raise")

    def make_wfn(self, board, pressure):
        od = self.opp_discard
        flop = self.flop
        use_disc = od is not None and len(flop) == 3
        if pressure < 0.05 and not use_disc:
            return None

        def wfn(opp):
            w = 1.0
            if pressure >= 0.05:
                s = made_strength(opp, board) if board else preflop_strength(opp)
                w = s ** pressure
            if use_disc and len(opp) == 2:
                kept = keep_value(opp, flop)
                alt = max(keep_value([opp[0], od], flop), keep_value([opp[1], od], flop))
                if alt > kept:
                    w *= 0.35
            return w
        return wfn

    # ---- decisions
    def choose_discard(self, req):
        hole = [CARD_INDEX[c] for c in req["hole_cards"]]
        flop = [CARD_INDEX[c] for c in req["board"]]
        self.hole = hole
        self.flop = flop
        card, _ = discard_choice(hole, flop, self.budget(req, 2.5))
        return {"type": "discard", "card": INDEX_CARD[card]}

    def hand_equity(self, req):
        board = [CARD_INDEX[c] for c in req.get("board", [])]
        if len(board) >= 3 and not self.flop:
            self.flop = board[:3]
        hole = self.hole
        dead = [self.opp_discard] if self.opp_discard is not None else []
        if len(hole) == 3 and len(board) < 3:
            opp_n = 3
        elif len(hole) == 3:
            opp_n = 3
        else:
            opp_n = 2
        p = self.pressure(req)
        budget = self.budget(req)
        if not board and len(hole) == 3:
            e = self.preflop_equity(hole, req)
            if e is not None:
                return e
        if not board and p < 0.05:
            key = tuple(sorted(hole))
            if key not in self.pf_cache:
                self.pf_cache[key] = equity(hole, [], dead, opp_n, budget)
            return self.pf_cache[key]
        return equity(hole, board, dead, opp_n, budget, wfn=self.make_wfn(board, p))

    def preflop_equity(self, hole, req):
        """Equity from the precomputed table, against the range the opponent's raises suggest."""
        row = PREFLOP.get(canon3(hole))
        if row is None:
            return None
        n_or = sum(1 for h in req.get("history") or []
                   if h.get("street") == "preflop" and h.get("actor") == "opp" and h.get("action") == "raise")
        agg = (0.25 / max(0.05, self.opp.raise_rate)) ** 0.5
        level = min(3.0, n_or * min(1.2, max(0.5, agg)))
        i = int(level)
        if i >= 3:
            return row[3]
        frac = level - i
        return row[i] * (1 - frac) + row[i + 1] * frac

    def choose_action(self, req):
        legal = req.get("legal_actions", [])
        street = req.get("street", "preflop")
        to_call = req.get("to_call", 0)
        pot = req.get("pot", 0)
        opp_bet = req.get("opp_bet", 0)
        can_raise = "raise" in legal and "min_raise" in req and "max_raise" in req
        lo = req.get("min_raise", 0)
        hi = req.get("max_raise", 0)

        def act(a):
            return {"type": "action", "action": a}

        def raise_to(amount):
            amount = int(max(lo, min(hi, int(amount))))
            if amount >= 0.7 * hi:
                amount = hi
            return {"type": "action", "action": "raise", "amount": amount}

        def passive():
            return act("check") if "check" in legal else act("fold")

        if len(self.hole) not in (2, 3):
            return act("check") if "check" in legal else (act("call") if to_call <= 2 and "call" in legal else act("fold"))

        mode = P["cfr_mode"]
        use_cfr = mode == 1 or (mode == 2 and street == "preflop") or (mode == 3 and street != "preflop")
        use_cfr = use_cfr or (mode == 4 and street != "preflop" and to_call == 0)
        use_cfr = use_cfr or (mode == 5 and street != "preflop" and to_call > 0)
        if use_cfr and mode == 5 and to_call < P.get("cfr_minfrac", 0.0) * max(1, pot - to_call):
            use_cfr = False
        if use_cfr:
            try:
                r = self.cfr_action(req, act, raise_to, lo, hi)
            except Exception:
                r = None
            if r is not None:
                try:
                    r = self.exploit_check(req, r)
                    r = self.river_big_check(req, r)
                except Exception:
                    pass
                return r
        e = self.hand_equity(req)
        rnd = random.random()
        om = self.opp

        if street == "preflop":
            if to_call > 0:
                odds = to_call / float(pot + to_call)
                if req.get("my_bet", 0) <= 1 and to_call == 1:  # button, first action
                    if can_raise and e > P['btn_open'] + 0.06 * rnd:
                        return raise_to(6)
                    if e > P['btn_call'] and "call" in legal:
                        return act("call")
                    return act("fold")
                if can_raise and e > P['pf_3bet'] and req.get("raises_left", 0) > 0:
                    if e > 0.80 and rnd < 0.5:
                        return raise_to(hi)
                    return raise_to(opp_bet * 3)
                margin = P['pf_margin'] - (om.bluff_rate - 0.2) * 0.25
                if e > odds + margin and "call" in legal:
                    return act("call")
                return act("fold")
            # big blind option after a limp
            if can_raise and e > P['bb_raise']:
                return raise_to(8)
            return act("check")

        # postflop: pick the move with the best expected chips.
        if P.get("ev_mode", 1):
            r = self.ev_postflop(req, e, act, raise_to, can_raise, lo, hi)
            try:
                r = self.river_big_check(req, r)
            except Exception:
                pass
            return r
        if to_call > 0:
            odds = to_call / float(pot + to_call)
            if can_raise and req.get("raises_left", 0) > 0 and e > P['value_raise']:
                return raise_to(opp_bet + 0.8 * (pot + to_call))
            margin = P['call_margin'] - (om.bluff_rate - 0.2) * 0.3
            if street == "river":
                margin += 0.02
            if e > odds + margin and "call" in legal:
                return act("call")
            return act("fold") if "fold" in legal else passive()

        if not can_raise:
            return act("check")
        if e > P['value_bet']:
            frac = 0.5 + 0.45 * min(1.0, (e - P['value_bet']) / 0.3)
            return raise_to(pot * frac)
        bluff_p = P['bluff'] * min(2.5, om.fold_rate / 0.4)
        if street == "river":
            bluff_p *= 0.8
        if e < 0.40 and rnd < bluff_p:
            return raise_to(pot * 0.6)
        if 0.45 < e <= P['value_bet'] and street != "river" and rnd < P['semi']:
            return raise_to(pot * 0.5)
        return act("check")

    def cfr_action(self, req, act, raise_to, lo, hi):
        """Action from the self-play strategy, or None to fall back to the normal logic."""
        street = req.get("street", "preflop")
        si = CFR_STREET.get(street)
        if si is None or self.seat not in ("button", "big_blind"):
            return None
        p = 0 if self.seat == "button" else 1
        board = [CARD_INDEX[c] for c in req.get("board", [])]
        pot = req.get("pot", 0)
        my_bet = req.get("my_bet", 0)
        opp_bet = req.get("opp_bet", 0)
        pot0 = pot - my_bet - opp_bet
        base = pot0 / 2.0
        # Replay this street in abstract terms.
        if si == 0:
            lv = {"me": 1 if p == 0 else 2, "opp": 2 if p == 0 else 1}
            last_raise = 2
        else:
            lv = {"me": 0, "opp": 0}
            last_raise = 0
        seq = ""
        raises = 1 if si == 0 else 0
        for h in req.get("history") or []:
            if h.get("street") != street:
                continue
            a = h.get("action")
            who = h.get("actor")
            oth = "opp" if who == "me" else "me"
            if a == "check":
                seq += "k"
            elif a == "call":
                seq += "c"
                lv[who] = lv[oth]
            elif a == "raise":
                amt = h.get("amount") or 0
                facing = max(0, lv[oth] - lv[who])
                pot_after = 2 * base + lv["me"] + lv["opp"] + facing
                inc = amt - lv[oth]
                if amt + base >= 0.85 * 200:
                    seq += "a"
                else:
                    seq += "h" if inc / max(1.0, pot_after) < 0.75 else "p"
                last_raise = max(2, inc)
                lv[who] = amt
                raises += 1
            elif a == "fold":
                return None
        if len(seq) > 8:
            return None
        pc = 0
        while pc < len(CFR_POT_CUTS) and max(pot0, 3) > CFR_POT_CUTS[pc]:
            pc += 1
        n = 60 if si == 1 else 100
        if self.time_short(req):
            n = 30
        g = cfr_group_of(cfr_strength(self.hole, board, n), CFR_CUTS[si])
        labs = cfr_labels(base + my_bet, base + opp_bet, my_bet, opp_bet, raises, last_raise)
        pre = "%d%d%d%d%s" % (p, si, g, pc, seq)
        key = pre + ":" + labs
        row = CFR_TABLE.get(key)
        if row is None:
            k2 = CFR_PREFIX.get(pre)
            if k2 is None:
                return None
            key = k2
            row = CFR_TABLE[k2]
        if row[-1] < P["cfr_min"]:
            return None
        labels = key.split(":")[1]
        probs = row[:-1]
        x = random.random() * sum(probs)
        i = 0
        acc = probs[0]
        while x > acc and i < len(probs) - 1:
            i += 1
            acc += probs[i]
        lab = labels[i]
        legal = req.get("legal_actions", [])
        to_call = opp_bet - my_bet
        if lab == "f":
            return act("fold") if "fold" in legal else act("check")
        if lab == "k":
            return act("check") if "check" in legal else None
        if lab == "c":
            return act("call") if "call" in legal else act("check")
        if "raise" not in legal or hi <= 0:
            return act("call") if "call" in legal else act("check")
        if lab == "a":
            return {"type": "action", "action": "raise", "amount": int(hi)}
        frac = 0.5 if lab == "h" else 1.0
        to = opp_bet + int(round(frac * (pot + to_call)))
        to = int(max(lo, min(hi, to)))
        return {"type": "action", "action": "raise", "amount": to}

    def exploit_check(self, req, r):
        """Overrule the self-play call/fold when this opponent's shown-down hands for this
        kind of bet say otherwise (enough observations needed)."""
        a = r.get("action")
        to_call = req.get("to_call", 0)
        street = req.get("street")
        if a not in ("call", "fold", "raise") or to_call <= 0 or street == "preflop":
            return r
        b = None
        nr = 0
        for i, st, actor, act, amt, size in replay(req.get("history") or []):
            if st != street or act != "raise":
                continue
            if actor == "opp":
                b = 3 if nr >= 1 else size_bucket(size or 0.0)
            nr += 1
        if b is None:
            return r
        o = self.opp.bet_obs.get((street, b))
        if not o or o[1] < P["xc_n"]:
            return r
        m = o[0] / o[1]  # average strength this opponent has shown with this kind of bet
        board = [CARD_INDEX[c] for c in req.get("board", [])]
        h = self.hole
        if len(h) == 3:
            ms = max(made_strength([h[0], h[1]], board), made_strength([h[0], h[2]], board),
                     made_strength([h[1], h[2]], board))
        else:
            ms = made_strength(h, board)
        pot = req.get("pot", 0)
        odds = to_call / float(pot + to_call)
        lst = self.opp.bet_list.get((street, b))
        if lst and len(lst) >= P["xq_n"]:
            beat = sum(1.0 if ms > x + 0.01 else (0.5 if ms >= x - 0.01 else 0.0) for x in lst) / len(lst)
            if a == "call" and beat < P["xq_fold"]:
                return {"type": "action", "action": "fold"}
            if a == "fold" and beat > P["xq_call"] and odds <= 0.40 and "call" in req.get("legal_actions", []):
                return {"type": "action", "action": "call"}
        if a in ("call", "raise") and m >= P["xc_hi"] and ms < m - 0.02:
            return {"type": "action", "action": "fold"}
        if (a == "fold" and o[1] >= P["xc_n"] + 1 and m <= P["xc_lo"] and ms >= max(0.38, m + 0.05)
                and odds <= 0.40 and "call" in req.get("legal_actions", [])):
            return {"type": "action", "action": "call"}
        return r

    def river_big_check(self, req, r):
        """Leak fix: big (not all-in) river bets are rarely bluffs in our test matches,
        and two pair or worse lost when calling them. Fold those hands instead."""
        if req.get("street") != "river" or r.get("action") not in ("call", "raise"):
            return r
        to_call = req.get("to_call", 0)
        pot = req.get("pot", 0)
        if to_call <= 0 or req.get("my_stack", 0) <= to_call or req.get("opp_stack", 1) == 0:
            return r  # all-in calls stay as they are
        if to_call < P["rv_big"] * max(1, pot - to_call):
            return r
        board = [CARD_INDEX[c] for c in req.get("board", [])]
        if len(self.hole) != 2 or made_strength(self.hole, board) >= P["rv_ms"]:
            return r
        return {"type": "action", "action": "fold"}

    def time_short(self, req):
        left = req.get("time_left_ms", self.time_bank_ms)
        return left < 0.25 * self.time_bank_ms

    def ev_postflop(self, req, e, act, raise_to, can_raise, lo, hi):
        """Expected-chips choice between fold/check/call and a few raise sizes."""
        legal = req.get("legal_actions", [])
        street = req.get("street")
        pot = float(req.get("pot", 0))
        to_call = req.get("to_call", 0)
        my_bet = req.get("my_bet", 0)
        opp_bet = req.get("opp_bet", 0)
        om = self.opp
        river = street == "river"
        # How much of our equity we actually realise if we just check/call.
        real = 1.0 if river else P["realize"]
        # Equity against the hands that fold: they are mostly weak.
        e_fold = 0.85 if river else P["e_fold"]

        options = []
        if to_call > 0:
            margin = P['call_margin'] - (om.bluff_rate - 0.2) * 0.3 + (0.02 if river else 0.0)
            ev_call = (e - margin) * real * (pot + to_call) - to_call
            options.append((ev_call, "call"))
            options.append((0.0, "fold"))
            nr = self.street_raises(req)
            base_fold = om.fold_rr_rate * (1.0 if nr <= 1 else 0.5)  # measured fold rate to our re-raises
        else:
            options.append((e * real * pot, "check"))
            base_fold = om.fold_rate
        if can_raise and req.get("raises_left", 0) > 0:
            seen = set()
            for frac in (0.4, 0.7, 1.1):
                target = int(max(lo, min(hi, opp_bet + frac * (pot + to_call))))
                if target >= 0.7 * hi:
                    target = hi
                if target in seen:
                    continue
                seen.add(target)
                add_me = target - my_bet
                add_opp = target - opp_bet
                size = add_opp / max(1.0, pot + to_call)
                f = base_fold * P["fold_scale"] * min(1.4, 0.75 + 0.45 * size)
                f = max(0.0, min(0.85, f))
                e_c = (e - f * e_fold) / (1.0 - f) if f < 1 else e
                e_c = max(0.02, min(e, e_c))
                if to_call > 0 and self.street_raises(req) >= 2 and e_c < 0.55:
                    continue  # never escalate a raising war without a strong hand
                ev = f * pot + (1 - f) * (e_c * (pot + add_me + add_opp) - add_me)
                options.append((ev, ("raise", target)))
        options.sort(key=lambda o: o[0], reverse=True)
        best = options[0][1]
        # Mix in a little unpredictability on close decisions.
        if len(options) > 1 and options[0][0] - options[1][0] < 0.03 * pot and random.random() < 0.25:
            best = options[1][1]
        if isinstance(best, tuple):
            return raise_to(best[1])
        if best == "call" and "call" in legal:
            return act("call")
        if best == "check" and "check" in legal:
            return act("check")
        if best == "fold" and "fold" in legal:
            return act("fold")
        return act("check") if "check" in legal else act("fold")


# ------------------------------------------------------------------ main

def safe_action(req):
    legal = req.get("legal_actions", []) if isinstance(req, dict) else []
    if "check" in legal:
        return {"type": "action", "action": "check"}
    if "call" in legal and req.get("to_call", 99) <= 4:
        return {"type": "action", "action": "call"}
    return {"type": "action", "action": "fold"}


def safe_discard(req):
    try:
        cards = req["hole_cards"]
        return {"type": "discard", "card": min(cards, key=lambda c: (RANKS.index(c[0]), SUITS.index(c[1])))}
    except Exception:
        return {"type": "discard", "card": "2s"}


def valid_action(reply, req):
    try:
        a = reply.get("action")
        if a not in req.get("legal_actions", []):
            return False
        if a == "raise":
            amt = reply.get("amount")
            return isinstance(amt, int) and req["min_raise"] <= amt <= req["max_raise"]
        return True
    except Exception:
        return False


def main():
    bot = Bot()
    out = sys.stdout
    for line in sys.stdin:
        line = line.strip()
        if not line:
            continue
        try:
            msg = json.loads(line)
        except Exception:
            continue
        if not isinstance(msg, dict):
            continue
        t = msg.get("type")
        reply = None
        if t == "action_request":
            try:
                reply = bot.choose_action(msg)
                if not valid_action(reply, msg):
                    reply = safe_action(msg)
            except Exception as exc:
                print("action error: %r" % (exc,), file=sys.stderr)
                reply = safe_action(msg)
        elif t == "discard_request":
            try:
                reply = bot.choose_discard(msg)
                if reply.get("card") not in msg.get("hole_cards", []):
                    reply = safe_discard(msg)
            except Exception as exc:
                print("discard error: %r" % (exc,), file=sys.stderr)
                reply = safe_discard(msg)
        elif t == "match_end":
            break
        else:
            try:
                bot.on_message(msg)
            except Exception as exc:
                print("state error: %r" % (exc,), file=sys.stderr)
            continue
        try:
            out.write(json.dumps(reply) + "\n")
            out.flush()
        except Exception:
            return


if __name__ == "__main__":
    main()
